import{_ as a,o as r,c as t,a2 as o}from"./chunks/framework.BjkiRu3Q.js";const m=JSON.parse('{"title":"Missing drafts and package errors","description":"","frontmatter":{},"headers":[],"relativePath":"help/website-draft-problems.md","filePath":"help/website-draft-problems.md"}'),i={name:"help/website-draft-problems.md"};function s(n,e,c,l,d,p){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="missing-drafts-and-package-errors" tabindex="-1">Missing drafts and package errors <a class="header-anchor" href="#missing-drafts-and-package-errors" aria-label="Permalink to &quot;Missing drafts and package errors&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Source-reviewed training draft · TransferBook+ v0.7.9. Verify installed release, permissions and configuration. Use authorized synthetic training data; no live activation is implied.</p></div><h2 id="my-website-draft-disappeared" tabindex="-1">My website draft disappeared <a class="header-anchor" href="#my-website-draft-disappeared" aria-label="Permalink to &quot;My website draft disappeared&quot;">​</a></h2><p>Verify the browser, profile, company and operating mode used when saving. Local drafts are scoped; previous unscoped drafts are not automatically transferred. Do not clear browser storage while recovery is pending.</p><h2 id="the-package-cannot-be-imported" tabindex="-1">The package cannot be imported <a class="header-anchor" href="#the-package-cannot-be-imported" aria-label="Permalink to &quot;The package cannot be imported&quot;">​</a></h2><p>Check whether you selected a compatible <code>.tbsite.json</code> or <code>.tbtheme.json</code>. A checksum mismatch, incompatible schema or unsafe content can block import. Re-export from the original workspace instead of editing the checksum manually.</p><h2 id="why-is-the-publish-control-locked" tabindex="-1">Why is the Publish control locked? <a class="header-anchor" href="#why-is-the-publish-control-locked" aria-label="Permalink to &quot;Why is the Publish control locked?&quot;">​</a></h2><p>A valid draft or approval is not sufficient proof of public publishing authorization. Check the configured publication gate and required permissions with an administrator. A template library may also have limited persistence in compatibility mode.</p><h2 id="recovery-checklist" tabindex="-1">Recovery checklist <a class="header-anchor" href="#recovery-checklist" aria-label="Permalink to &quot;Recovery checklist&quot;">​</a></h2><p>Keep the original export, note the installed release, record the validation error without confidential content, and recover from the original browser context if available. Do not copy storage keys across companies.</p><p>See <a href="/websites/draft-storage.html">Local drafts and recovery</a> and <a href="/websites/template-manager.html">Template Manager</a>.</p><h2 id="recovery-and-hosting-in-newer-staging-releases" tabindex="-1">Recovery and hosting in newer staging releases <a class="header-anchor" href="#recovery-and-hosting-in-newer-staging-releases" aria-label="Permalink to &quot;Recovery and hosting in newer staging releases&quot;">​</a></h2><p>In v0.7.10, inspect the autosave recovery banner and use a full workspace backup where available. Restore in the correct company and operating mode, then explicitly save and verify. See <a href="/websites/draft-storage.html">Local drafts and recovery</a>.</p><p>In v0.7.11, a missing hosting panel or locked update control may reflect the default-off restricted demo capability, company scope or permissions. A prepared revision does not mean the public site changed. If an authorized update or rollback has an uncertain outcome, do not retry: ask the owner to inspect exact revision fingerprints and recovery records. See <a href="/websites/publication-controls.html">Publication controls</a>.</p>',14)])])}const f=a(i,[["render",s]]);export{m as __pageData,f as default};
